	private void assertPinnedReaderAbortsAfterRealMapGrowth(IsolationLevel readerIsolation, String subjectPrefix,
			String valuePrefix) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			int initialRows = seed(repository, INITIAL_READER_ROWS);
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open();
					SailRepositoryConnection reader = repository.getConnection();
					SailRepositoryConnection writer = repository.getConnection()) {
				reader.begin(readerIsolation);
				try (RepositoryResult<Statement> openResult = reader.getStatements(null, PREDICATE, null, false)) {
					assertThat(openResult.hasNext()).as(readerIsolation + " reader must have rows before growth")
							.isTrue();
					openResult.next();
					for (int round = 0; round < LIVE_TRIPLE_GROWTH_ROUNDS; round++) {
						writer.begin(IsolationLevels.READ_COMMITTED);
						addRows(writer, subjectPrefix, valuePrefix, round * ROWS_PER_COMMIT, ROWS_PER_COMMIT);
						writer.commit();
					}

					assertThat(resizeLogs.tripleResizeMessages())
							.as("triple map must resize while " + readerIsolation + " reader remains open")
							.isNotEmpty();
					assertThat(resizeLogs.valueResizeMessages())
							.as("value map must resize while " + readerIsolation + " reader remains open")
							.isNotEmpty();
					if (readerIsolation.isCompatibleWith(IsolationLevels.SNAPSHOT)) {
						assertThatThrownBy(reader::size)
								.as("pinned " + readerIsolation + " transaction must reject a resized snapshot")
								.isInstanceOf(RepositoryException.class)
								.hasMessageContaining("SNAPSHOT");
					} else {
						int remaining = 0;
						while (openResult.hasNext()) {
							openResult.next();
							remaining++;
						}
						assertThat(remaining).as("an open SNAPSHOT_READ query keeps its original snapshot")
								.isEqualTo(initialRows - 1);
						assertThat(reader.size()).as("a new SNAPSHOT_READ query sees committed map growth")
								.isEqualTo(initialRows + LIVE_TRIPLE_GROWTH_ROWS);
					}
				}

				reader.rollback();
				reader.begin(IsolationLevels.READ_COMMITTED);
				assertThat(countRows(reader)).as("a fresh transaction must see committed rows after retry")
						.isEqualTo(initialRows + LIVE_TRIPLE_GROWTH_ROWS);
				reader.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void rollbackHidesLargeWriterUntilCommitAcrossRealMapGrowth() throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			seed(repository);
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open();
					SailRepositoryConnection reader = repository.getConnection();
					SailRepositoryConnection writer = repository.getConnection()) {
				reader.begin(IsolationLevels.READ_COMMITTED);

				writer.begin(IsolationLevels.READ_COMMITTED);
				addRows(writer, "rollback-subject:", "rollback-value:", 0, GROWING_TRANSACTION_ROWS);
				assertThat(countRows(reader)).as("uncommitted writer rows must stay invisible").isEqualTo(1);
				writer.rollback();
				assertThat(countRows(reader)).as("rolled-back rows must stay absent").isEqualTo(1);

				writer.begin(IsolationLevels.READ_COMMITTED);
				addRows(writer, "committed-subject:", "committed-value:", 0, GROWING_TRANSACTION_ROWS);
				writer.commit();
				assertThat(countRows(reader)).as("committed rows must become visible")
						.isEqualTo(1 + GROWING_TRANSACTION_ROWS);
				reader.commit();
				assertThat(resizeLogs.tripleResizeMessages())
						.as("triple map must resize when the committed record cache is flushed")
						.isNotEmpty();
				assertThat(resizeLogs.valueResizeMessages())
						.as("value map must resize when the committed record cache is flushed")
						.isNotEmpty();
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void concurrentReaderAndWriterCompleteAcrossRealMapGrowth() throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfigWithShadowAdjacency());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			int initialRows = seed(repository, OPEN_READER_ROWS);
			Set<Statement> initialStatements = expectedInitialStatements(OPEN_READER_ROWS);
			Set<Statement> allowedStatements = new HashSet<>(initialStatements);
			allowedStatements.addAll(
					expectedStatements("concurrent-subject:", "concurrent-value:", 0,
							LIVE_TRIPLE_GROWTH_ROWS));
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open()) {
				long startedNanos = System.nanoTime();
				List<String> phases = new CopyOnWriteArrayList<>();
				CountDownLatch readerReady = new CountDownLatch(1);
				CountDownLatch writerFinished = new CountDownLatch(1);
				ExecutorService executor = Executors.newFixedThreadPool(2);
				markPhase(phases, startedNanos, "executor-created");
				Future<?> readerFuture = executor.submit(() -> {
					markPhase(phases, startedNanos, "reader-task-started");
					try (SailRepositoryConnection reader = repository.getConnection()) {
						reader.begin(IsolationLevels.READ_COMMITTED);
						markPhase(phases, startedNanos, "reader-transaction-begun");
						try (RepositoryResult<Statement> statements = reader.getStatements(null, PREDICATE, null,
								false)) {
							markPhase(phases, startedNanos, "reader-cursor-opened");
							assertThat(statements.hasNext()).as("concurrent reader must see initial rows").isTrue();
							Set<Statement> seen = new HashSet<>();
							assertKnownAndUnique(allowedStatements, seen, statements.next());
							readerReady.countDown();
							markPhase(phases, startedNanos, "reader-first-row-and-ready");
							markPhase(phases, startedNanos, "reader-awaiting-writer");
							assertThat(writerFinished.await(30, TimeUnit.SECONDS)).isTrue();
							markPhase(phases, startedNanos, "reader-writer-finished");
							markPhase(phases, startedNanos, "reader-drain-started");
							while (statements.hasNext()) {
								assertKnownAndUnique(allowedStatements, seen, statements.next());
							}
							markPhase(phases, startedNanos, "reader-drain-finished");
							assertThat(seen.containsAll(initialStatements))
									.as("a concurrent reader must retain every pre-growth statement")
									.isTrue();
							assertThat(seen.size())
									.as("a concurrent reader must contain only known committed statements")
									.isBetween(initialRows, initialRows + LIVE_TRIPLE_GROWTH_ROWS);
						}
						reader.commit();
					}
					return null;
				});
				Future<?> writerFuture = executor.submit(() -> {
					markPhase(phases, startedNanos, "writer-task-started");
					try {
						markPhase(phases, startedNanos, "writer-awaiting-reader");
						assertThat(readerReady.await(30, TimeUnit.SECONDS)).isTrue();
						markPhase(phases, startedNanos, "writer-reader-ready");
						try (SailRepositoryConnection writer = repository.getConnection()) {
							writer.begin(IsolationLevels.READ_COMMITTED);
							markPhase(phases, startedNanos, "writer-transaction-begun");
							addRows(writer, "concurrent-subject:", "concurrent-value:", 0, LIVE_TRIPLE_GROWTH_ROWS);
							markPhase(phases, startedNanos, "writer-rows-added");
							markPhase(phases, startedNanos, "writer-commit-started");
							writer.commit();
							markPhase(phases, startedNanos, "writer-commit-finished");
							assertThat(resizeLogs.tripleResizeMessages())
									.as("concurrent commit must resize the triple map before writer release")
									.isNotEmpty();
							assertThat(resizeLogs.valueResizeMessages())
									.as("concurrent commit must resize the value map before writer release")
									.isNotEmpty();
							markPhase(phases, startedNanos, "writer-resize-events-observed");
						}
					} finally {
						writerFinished.countDown();
						markPhase(phases, startedNanos, "writer-finished-latch-released");
					}
					return null;
				});
				markPhase(phases, startedNanos, "both-futures-submitted");
				long futureDeadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(45);
				List<Throwable> futureFailures = new ArrayList<>(2);
				AssertionError diagnosticFailure = null;
				Throwable cleanupFailure = null;
				try {
					Throwable writerFailure = awaitFuture(writerFuture, startedNanos, futureDeadlineNanos, "writer",
							phases);
					if (writerFailure != null) {
						futureFailures.add(writerFailure);
					}
					Throwable readerFailure = awaitFuture(readerFuture, startedNanos, futureDeadlineNanos, "reader",
							phases);
					if (readerFailure != null) {
						futureFailures.add(readerFailure);
					}
					if (!futureFailures.isEmpty()) {
						markPhase(phases, startedNanos, "future-failure-before-cancellation");
						diagnosticFailure = new AssertionError(
								"concurrent reader/writer futures did not complete; phases=" + phases
										+ "\nthread dump before cancellation:\n" + threadDump());
						for (Throwable failure : futureFailures) {
							diagnosticFailure.addSuppressed(failure);
						}
					}
				} finally {
					readerReady.countDown();
					writerFinished.countDown();
					markPhase(phases, startedNanos, "both-latches-released-for-cleanup");
					executor.shutdownNow();
					try {
						if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
							cleanupFailure = new TimeoutException(
									"reader and writer did not terminate after cancellation");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						cleanupFailure = interrupted;
					}
				}
				if (diagnosticFailure != null) {
					if (cleanupFailure != null) {
						diagnosticFailure.addSuppressed(cleanupFailure);
					}
					throw diagnosticFailure;
				}
				if (cleanupFailure != null) {
					AssertionError failure = new AssertionError("reader and writer cleanup failed");
					failure.initCause(cleanupFailure);
					throw failure;
				}
				try (SailRepositoryConnection reader = repository.getConnection()) {
					reader.begin(IsolationLevels.READ_COMMITTED);
					assertThat(countRows(reader)).as("fresh reader must see committed concurrent rows")
							.isEqualTo(initialRows + LIVE_TRIPLE_GROWTH_ROWS);
					reader.commit();
				}
				assertThat(resizeLogs.tripleResizeMessages()).as("concurrent commit must resize the triple map")
						.isNotEmpty();
				assertThat(resizeLogs.valueResizeMessages()).as("concurrent commit must resize the value map")
						.isNotEmpty();
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void markPhase(List<String> phases, long startedNanos, String phase) {
		long elapsedMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startedNanos);
		phases.add(elapsedMillis + " ms [" + Thread.currentThread().getName() + "] " + phase);
	}

	private static Throwable awaitFuture(Future<?> future, long startedNanos, long deadlineNanos, String name,
			List<String> phases) {
		long remainingNanos = deadlineNanos - System.nanoTime();
		if (remainingNanos <= 0) {
			markPhase(phases, startedNanos, name + "-deadline-expired-before-wait");
			return new TimeoutException(name + " future deadline expired before wait");
		}
		try {
			future.get(remainingNanos, TimeUnit.NANOSECONDS);
			markPhase(phases, startedNanos, name + "-future-completed");
			return null;
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			markPhase(phases, startedNanos, name + "-future-interrupted");
			return interrupted;
		} catch (ExecutionException failure) {
			markPhase(phases, startedNanos, name + "-future-failed: " + failure.getCause());
			return failure.getCause();
		} catch (TimeoutException timeout) {
			markPhase(phases, startedNanos, name + "-future-timed-out");
			return timeout;
		} catch (CancellationException cancellation) {
			markPhase(phases, startedNanos, name + "-future-cancelled");
			return cancellation;
		}
	}

	private static String threadDump() {
		ThreadMXBean threadBean = ManagementFactory.getThreadMXBean();
		ThreadInfo[] threadInfos = threadBean.getThreadInfo(threadBean.getAllThreadIds(), 64);
		StringBuilder dump = new StringBuilder();
		for (ThreadInfo threadInfo : threadInfos) {
			if (threadInfo != null && (threadInfo.getThreadName().equals("main")
					|| threadInfo.getThreadName().startsWith("pool-"))) {
				dump.append(threadInfo).append(System.lineSeparator());
			}
		}
		return dump.toString();
	}

